t++||createCanvas(W=(w=200)*2,W)+noStroke()
for(x=0;x<W;x+=d)
for(y=0;y<W;y+=d)
!C[x]?C[x]=[]:0,
fill(!C[x][y]?C[x][y]=[r(w),r(W),r(w)]:C[x][y]),
M=mag(X=x-w,Y=y-w),
T=atan2(Y,X),
rect(x+M*cos(U=T+t/40),y+M*sin(U),d/2)
}

